#!/usr/bin/env bash
# SegFormer-B5 crop longtrain, stage 1 (Scene5-val 20k) — NATIVE UBUNTU RESUME from iter_1000.pth.
# Adapted 2026-11-14 from 11_b5_crop_lt_queue_wsl.sh (WSL) per handoff 2026-11-13.
# Only differences from the killed WSL run:
#   - native bash, ROOT on the mounted NTFS tree, conda env ~/miniconda3/envs/lusnar
#   - data-root $ROOT/data (WSL used /root/lusnar_data)
#   - list-dir data/lists_b5_crop is regenerated by the trainer; its full_crater_weights.json
#     is freshly computed (old D:\ path cache must NOT be reused: pairs check would fail)
#   - adds --resume work_dirs/LT_B5_crop_20k/iter_1000.pth
#   - new log file; WSL crash logs are left untouched
# Python argv otherwise identical: M_ROW_BLV, 20000 iters, crop 512, batch/gpu 24, lr 6e-5,
# bf16, seed 42, val every 1000 on full Scene5, --tta-final, workers 12, port 29700.
# Never: plus5 (not chained), Moon_2/4/9, official submit, PYTORCH_CUDA_ALLOC_CONF,
# overwriting existing work dirs, single-GPU fallback.
set -uo pipefail

ROOT=/run/media/cui/数据/LuSNAR_Seg
export PYTHONPATH="$ROOT/tools/portable"
export PYTHONUNBUFFERED=1
unset PYTORCH_CUDA_ALLOC_CONF || true
PY=$HOME/miniconda3/envs/lusnar/bin/python
cd "$ROOT" || exit 90

RUN=LT_B5_crop_20k
W="$ROOT/work_dirs/$RUN"
CKPT="$W/iter_1000.pth"
BATCH="${LT_BATCH:-24}"
WORKERS="${LT_WORKERS:-12}"
ITERS=20000
PORT=29700
LIST="$ROOT/data/lists_b5_crop"
LOG="$ROOT/logs/${RUN}_ubuntu_resume.log"
B5PRE="$ROOT/pretrained/mit_b5_20220624-658746d9.pth"

say() { echo "[$(date '+%F %T')] $*" | tee -a "$LOG"; }

say "ubuntu resume start pid=$$ run=$RUN batch/gpu=$BATCH workers/rank=$WORKERS iters=$ITERS"

# --- preflight (no overwrite of anything; resume target must exist) ---
[ -f "$CKPT" ] || { say "REFUSE: missing $CKPT"; exit 2; }
[ -f "$B5PRE" ] || { say "REFUSE: missing $B5PRE"; exit 3; }
[ -x "$PY" ] || { say "REFUSE: missing python $PY"; exit 7; }
if pgrep -f 'lusnar_row_blv_ddp|lusnar_small_crater_score_sc|torch.distributed.run' >/dev/null; then
  say "REFUSE: training/scoring process running"
  pgrep -af 'lusnar_row_blv_ddp|lusnar_small_crater_score_sc|torch.distributed.run' | tee -a "$LOG"
  exit 4
fi
if ! nvidia-smi --query-gpu=memory.used --format=csv,noheader,nounits | awk 'BEGIN{x=0}{if($1+0>4000)x=1}END{exit x}'; then
  say "REFUSE: GPU busy: $(nvidia-smi --query-gpu=memory.used --format=csv,noheader,nounits | tr '\n' ' ')"
  exit 5
fi
if ss -ltn 2>/dev/null | awk '{print $4}' | grep -q ":$PORT$"; then
  say "REFUSE: port $PORT busy"
  exit 6
fi
say "POWER before launch: $(nvidia-smi --query-gpu=index,power.limit,power.draw --format=csv,noheader | tr '\n' ' | ')"
mkdir -p "$LIST"

say "RESUME from $CKPT"
echo "=== $RUN UBUNTU RESUME start $(date '+%F %T') trainer=lusnar_row_blv_ddp_b5.py batch/gpu=$BATCH x2 crop=512 lr=6e-5 workers=$WORKERS iters=$ITERS resume=$CKPT ===" >>"$LOG"
"$PY" -u -m torch.distributed.run --nproc_per_node=2 --master_addr 127.0.0.1 --master_port "$PORT" \
  tools/portable/lusnar_row_blv_ddp_b5.py \
  --recipe M_ROW_BLV --run-name "$RUN" --iters "$ITERS" --batch "$BATCH" --workers "$WORKERS" \
  --amp bf16 --crop 512 --lr 6e-5 --val-every 1000 --log-every 50 --tta-final \
  --pretrain "$B5PRE" \
  --project-root "$ROOT" --data-root "$ROOT/data" --list-dir "$LIST" --train-subdir train \
  --resume "$CKPT" \
  >>"$LOG" 2>&1 < /dev/null
rc=$?
echo "=== $RUN UBUNTU RESUME exit $rc $(date '+%F %T') ===" >>"$LOG"
say "END $RUN exit=$rc"
exit $rc
